package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.Locale;
import java.util.Set;
import net.officefloor.hq.app.claim.Tags;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Bind the body and refuse it before anything is read or written: a name is required, the grade
 *  is one of A, B or C, the grade's from-date (optional) a real yyyy-mm-dd date, the terms (optional)
 *  blank or a whole number of days. Publishes the request with its name trimmed and its contact (optional)
 *  trimmed and lower-cased, and its tags (optional) normalised as a claim's are (see Tags.normalise). */
public class ValidatePerson {
    private static final Set<String> GRADES = Set.of("A", "B", "C");

    public void validate(@RequestBody PersonRequest request, Out<PersonRequest> body) throws InvalidPersonException {
        body.set(check(request));
    }

    /** The request as the person form's rules leave it, or refused by them. */
    static PersonRequest check(PersonRequest request) throws InvalidPersonException {
        if (request == null || request.user() == null || request.user().isBlank()) {
            throw new InvalidPersonException("Sign in before changing people.");
        }
        String name = request.name() == null ? "" : request.name().trim();
        if (name.isEmpty()) {
            throw new InvalidPersonException("A name is required.");
        }
        if (name.length() > 200) {
            throw new InvalidPersonException("A name is at most 200 characters.");
        }
        String grade = request.grade() == null ? "" : request.grade().trim();
        if (!GRADES.contains(grade)) {
            throw new InvalidPersonException("The grade must be A, B or C.");
        }
        String gradeFrom = request.gradeFrom() == null ? "" : request.gradeFrom().trim();
        if (!gradeFrom.isEmpty()) {
            try {
                LocalDate.parse(gradeFrom);
            } catch (DateTimeParseException e) {
                throw new InvalidPersonException("The grade's from-date must be a date, yyyy-mm-dd.");
            }
        }
        String terms = request.terms() == null ? null : request.terms().trim();
        if (terms != null && !terms.isEmpty() && !terms.matches("\\d{1,4}")) {
            throw new InvalidPersonException("The terms must be a whole number of days, 0 or more, or blank for none.");
        }
        String contact = request.contact() == null ? null : request.contact().trim().toLowerCase(Locale.ROOT);
        if (contact != null && contact.length() > 200) {
            throw new InvalidPersonException("A contact is at most 200 characters.");
        }
        String tags = request.tags() == null ? null : Tags.normalise(request.tags());
        if (tags != null && tags.length() > 1000) {
            throw new InvalidPersonException("Tags are at most 1000 characters.");
        }
        return new PersonRequest(request.user().trim(), name, grade, request.version(),
                gradeFrom.isEmpty() ? null : gradeFrom,
                terms == null || terms.isEmpty() ? terms : String.valueOf(Integer.parseInt(terms)), contact, tags);
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

/** Fails when the person is not on the sheet. */
public class LoadPerson {
    public void load(@PathVariable("sheetId") String sheetId, @PathVariable("personId") String personId,
            PersonRepository repository, Out<Person> person) throws PersonNotFoundException {
        Person found = null;
        try {
            found = repository.find(sheetId.trim(), Long.parseLong(personId.trim()));
        } catch (NumberFormatException e) {
            // not an id: not found
        }
        if (found == null) {
            throw new PersonNotFoundException(personId);
        }
        person.set(found);
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Apply the edit to the loaded person and store it, refused when the person has been saved since
 *  the version the edit was made from. The grade is recorded from the edit's from-date (the sheet's today
 *  when none was given), keeping the grades already recorded from other dates. The person's own terms are set when the edit gives
 *  them (cleared when given blank), and so are their contact and tags. */
public class SavePerson {
    public void save(@Val PersonRequest request, @Val Person loaded, PersonRepository repository,
            SheetRepository sheets, Out<PersonResponse> saved) throws StalePersonException {
        long from = request.version() == null ? loaded.version() : request.version();
        Person person = new Person(loaded.id(), loaded.sheetId(), request.name(), loaded.grade(), from + 1,
                loaded.statementCount(), loaded.statedTotal(), loaded.statementDate(), loaded.retiredFrom(),
                loaded.grades(), loaded.holds(), loaded.terms(), loaded.contact(), loaded.aliases(), loaded.origin(),
                loaded.retirements(), loaded.tags());
        if (!repository.update(person, from)) {
            throw new StalePersonException(loaded.name());
        }
        LocalDate gradeFrom = request.gradeFrom() != null ? LocalDate.parse(request.gradeFrom())
                : sheets.today(loaded.sheetId());
        repository.grade(person, request.grade(), gradeFrom);
        if (request.terms() != null) {
            repository.terms(person, request.terms().isEmpty() ? null : Integer.valueOf(request.terms()));
        }
        if (request.contact() != null) {
            repository.contact(person, request.contact().isEmpty() ? null : request.contact());
        }
        if (request.tags() != null) {
            repository.tags(person, request.tags().isEmpty() ? null : request.tags());
        }
        saved.set(PersonResponse.from(repository.find(loaded.sheetId(), loaded.id())));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;

/** Record the stored edit in the audit file; the person's own terms whenever the edit gives them (blank: cleared),
 *  and likewise their contact. */
public class AuditPersonEdited {
    public void audit(@Val PersonRequest request, @Val Person loaded, @Val PersonResponse saved, Audit audit) {
        audit.record("PERSON_EDITED sheet=" + loaded.sheetId() + " by=" + request.user()
                + " name=" + saved.name() + " grade=" + saved.grade()
                + (request.terms() != null ? " terms=" + request.terms() : "")
                + (request.contact() != null ? " contact=" + request.contact() : ""));
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Bind the body and refuse it before anything is read or written: a signed-in user, and the from- and to-dates,
 *  when given, real yyyy-mm-dd dates, the to-date not before the from-date. */
public class ValidateHold {
    public void validate(@RequestBody HoldRequest request, Out<HoldInput> body) throws InvalidPersonException {
        if (request == null || request.user() == null || request.user().isBlank()) {
            throw new InvalidPersonException("Sign in before holding people.");
        }
        LocalDate from = date(request.from(), "from");
        LocalDate to = date(request.to(), "to");
        if (from != null && to != null && to.isBefore(from)) {
            throw new InvalidPersonException("The hold's to-date must not be before its from-date.");
        }
        body.set(new HoldInput(request.user().trim(), from, to));
    }

    private static LocalDate date(String value, String which) throws InvalidPersonException {
        String raw = value == null ? "" : value.trim();
        if (raw.isEmpty()) {
            return null;
        }
        if (!raw.matches("\\d{4}-\\d{2}-\\d{2}")) {
            throw new InvalidPersonException("The hold's " + which + "-date must be a date (yyyy-mm-dd).");
        }
        try {
            return LocalDate.parse(raw);
        } catch (DateTimeParseException e) {
            throw new InvalidPersonException("The hold's " + which + "-date must be a real date (yyyy-mm-dd).");
        }
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;

/** A validated hold. The from-date is null when the sheet's today is to be used; the to-date is null when the hold
 *  is open-ended. */
public record HoldInput(String user, LocalDate from, LocalDate to) {
}

